"""Evaluation evidence, loaded from models/evidence.json (generated by train_models.py).
Nothing here is typed in by hand: re-running train_models.py regenerates every number the app shows."""
import json

import pandas as pd

from .config import MODELS_DIR, RECOMMENDED_MODEL

EVIDENCE_PATH = MODELS_DIR / "evidence.json"
MODELS = ["Logistic Regression", "Decision Tree", "Gaussian Naive Bayes"]
AVAILABLE = EVIDENCE_PATH.exists()

test_overall = test_not_attending = cv_main = cv_ap = generalization = None
threshold_oof = threshold_test = None
subgroup_age = subgroup_region = subgroup_sex = subgroup_residence = None
confusion, DATASET_FACTS, F = {}, {}, {}
SELECTED_THRESHOLD, SELECTION_RULE = 0.40, ""
_age_by_thr = {}


def _row(df, model):
    return df.loc[df["Model"] == model].iloc[0]


def _load():
    global test_overall, test_not_attending, cv_main, cv_ap, generalization, threshold_oof, threshold_test
    global subgroup_age, subgroup_region, subgroup_sex, subgroup_residence, confusion, DATASET_FACTS, F
    global SELECTED_THRESHOLD, SELECTION_RULE, _age_by_thr
    e = json.loads(EVIDENCE_PATH.read_text(encoding="utf-8"))
    test_overall, test_not_attending = pd.DataFrame(e["test_overall"]), pd.DataFrame(e["test_not_attending"])
    cv_main, cv_ap, generalization = pd.DataFrame(e["cv_main"]), pd.DataFrame(e["cv_ap"]), pd.DataFrame(e["generalization"])
    threshold_oof, threshold_test = pd.DataFrame(e["threshold_oof"]), pd.DataFrame(e["threshold_test"])
    subgroup_age, subgroup_region = pd.DataFrame(e["subgroup_age"]), pd.DataFrame(e["subgroup_region"])
    subgroup_sex, subgroup_residence = pd.DataFrame(e["subgroup_sex"]), pd.DataFrame(e["subgroup_residence"])
    confusion, DATASET_FACTS = e["confusion"], e["dataset"]
    SELECTED_THRESHOLD, SELECTION_RULE = float(e["selected_threshold"]), e["selection_rule"]
    _age_by_thr = e["age_recall_by_threshold"]

    s = SELECTED_THRESHOLD
    lr, dt, nb = MODELS
    at = lambda df, t: df.loc[(df["Threshold"] - t).abs() < 1e-9].iloc[0]
    oof_s, oof_d, te_s, te_d = at(threshold_oof, s), at(threshold_oof, .5), at(threshold_test, s), at(threshold_test, .5)
    reg = subgroup_region.sort_values("Recall @selected")
    age = subgroup_age.set_index("Age group")
    F = {
        "thr": s, "rule": SELECTION_RULE,
        "lr_acc": _row(test_overall, lr)["Accuracy"], "dt_acc": _row(test_overall, dt)["Accuracy"],
        "nb_acc": _row(test_overall, nb)["Accuracy"],
        "lr_prec": _row(test_not_attending, lr)["Precision (not attending)"],
        "lr_rec": _row(test_not_attending, lr)["Recall (not attending)"],
        "dt_rec": _row(test_not_attending, dt)["Recall (not attending)"],
        "nb_prec": _row(test_not_attending, nb)["Precision (not attending)"],
        "nb_rec": _row(test_not_attending, nb)["Recall (not attending)"],
        "lr_ap": _row(test_not_attending, lr)["AP (not attending)"],
        "dt_ap": _row(test_not_attending, dt)["AP (not attending)"],
        "nb_ap": _row(test_not_attending, nb)["AP (not attending)"],
        "lr_cv_ap": _row(cv_ap, lr)["AP not attending (mean)"], "dt_cv_ap": _row(cv_ap, dt)["AP not attending (mean)"],
        "lr_cv_rec": _row(cv_main, lr)["Recall not attending (mean)"],
        "dt_cv_rec": _row(cv_main, dt)["Recall not attending (mean)"],
        "max_cv_acc_sd": float(cv_main["Accuracy (SD, pp)"].max()),
        "dt_train_acc": _row(generalization, dt)["Training accuracy"], "dt_test_acc": _row(generalization, dt)["Test accuracy"],
        "dt_gap": _row(generalization, dt)["Train–test gap (pp)"], "lr_gap": _row(generalization, lr)["Train–test gap (pp)"],
        "oof_prec_s": oof_s["Precision (not attending)"], "oof_rec_s": oof_s["Recall (not attending)"],
        "oof_f1_s": oof_s["F1 (not attending)"], "oof_prec_d": oof_d["Precision (not attending)"],
        "oof_rec_d": oof_d["Recall (not attending)"], "oof_f1_d": oof_d["F1 (not attending)"],
        "te_prec_s": te_s["Precision (not attending)"], "te_rec_s": te_s["Recall (not attending)"],
        "te_prec_d": te_d["Precision (not attending)"], "te_rec_d": te_d["Recall (not attending)"],
        "lr_cm": confusion[lr], "nb_cm": confusion[nb],
        "age_min_grp": age["Recall @selected"].idxmin(), "age_min": age["Recall @selected"].min(),
        "age_min_d": age.loc[age["Recall @selected"].idxmin(), "Recall @0.50"],
        "age_max_grp": age["Recall @selected"].idxmax(), "age_max": age["Recall @selected"].max(),
        "age_young_n": int(age.loc["5–9", "Not attending (n)"]),
        "reg_min": reg.iloc[0]["Region"], "reg_min_v": reg.iloc[0]["Recall @selected"],
        "reg_max": reg.iloc[-1]["Region"], "reg_max_v": reg.iloc[-1]["Recall @selected"],
        "sex_gap": abs(subgroup_sex["Recall @selected"].max() - subgroup_sex["Recall @selected"].min()),
        "res_gap": abs(subgroup_residence["Recall @selected"].max() - subgroup_residence["Recall @selected"].min()),
    }


def age_recall(group: str, t: float):
    """Test-set not-attending recall for an age group at threshold t (recommended model)."""
    return _age_by_thr.get(f"{t:.2f}", {}).get(group)


if AVAILABLE:
    _load()
